import{_ as t,C as l,o as r,c as i,j as e,a as o,E as n,a6 as s}from"./chunks/framework.CnPv4DE1.js";const _=JSON.parse('{"title":"如果你想在10年后不被时代淘汰，请学习这项技能","description":"","frontmatter":{"title":"如果你想在10年后不被时代淘汰，请学习这项技能","originalTitle":"Learn This Skill If You Want To Stay Relevant In 10 Years","date":"2024-07-06","originalUrl":"https://thedankoe.com/letters/learn-this-skill-if-you-want-to-stay-relevant-in-10-years/","minutes":16,"sourceHash":"5c061f00fc7fe34e7908e7e85ee94296c1a35301a86c5219fb359a5235f82e4b","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/learn-this-skill-if-you-want-to-stay-relevant-in-10-years/"}]]},"headers":[],"relativePath":"letters/learn-this-skill-if-you-want-to-stay-relevant-in-10-years.md","filePath":"letters/learn-this-skill-if-you-want-to-stay-relevant-in-10-years.md"}'),h={name:"letters/learn-this-skill-if-you-want-to-stay-relevant-in-10-years.md"};function c(m,p,u,d,f,b){const a=l("ArticleMeta");return r(),i("div",null,[p[0]||(p[0]=e("h1",{id:"如果你想在10年后不被时代淘汰-请学习这项技能",tabindex:"-1"},[o("如果你想在10年后不被时代淘汰，请学习这项技能 "),e("a",{class:"header-anchor",href:"#如果你想在10年后不被时代淘汰-请学习这项技能","aria-label":'Permalink to "如果你想在10年后不被时代淘汰，请学习这项技能"'},"​")],-1)),n(a),p[1]||(p[1]=s('<p><a href="https://www.youtube.com/embed/tkrlxYTRU_M?si=1S9W8at5n244DLbt" target="_blank" rel="noreferrer">观看原文视频</a></p><p>问题所在：</p><p>人们从小就被设定好了程序：要依靠除了自己以外的任何人来保障自己的未来。</p><ul><li>活在过去、与新机遇脱节的父母。</li><li>由它们把你训练去适应的那个系统所资助的学校。</li><li>从你不去寻找更好选择中获利的雇主（而且他们很可能会在未来10年内解雇你）。</li><li>用新闻、梗图和其他控制你情绪健康的噪音来分散你注意力的社会。</li></ul><p>这是一个通向缺乏保障的未来的完美公式。</p><p>学这个。做那个。去考试。信这个神。找这份工作。</p><p>当你开始摸索20多岁的人生时，你的大脑已经变成了一个一遍又一遍运行相同功能的计算机程序。</p><p>起床。上班。付出最低限度的努力。付账单。刷社交媒体。怀念过去。担忧明天。偶尔瞥见一眼未来：在那里，你虚妄的安全感将受到AI、自动化或仅仅是生活随机性的威胁。</p><p>你的人生不存在“什么都不做”的选项。</p><p>只有做你想做的事，或者做别人想让你做的事。</p><p>而如果你选择后者，你的生活就会变得越来越机械化，直到几乎无法逃脱。</p><p>解决方案：</p><p><em>变得独立。</em></p><p>自己去思考。</p><p>为自己赚钱。</p><p>潜入未知。</p><p>创造你自己的安全感。</p><p>反抗生活中所有世俗的道路，因为那是为真理留出空间的唯一途径。</p><p>克里希那穆提（Krishnamurti）曾写道：</p><blockquote><p>生活其实是非常美好的，它并不是我们弄成的这种丑陋模样；只有当你反抗一切——反抗有组织的宗教，反抗传统，反抗当前这个腐朽的社会时，你才能欣赏到它的丰富、它的深度、它非凡的可爱之处——从而让你作为一个人类，自己去发现什么是真实的。不去模仿，而是去发现——这才是教育，不是吗？</p></blockquote><p>这就给我们留下了一项任务：</p><p>敞开心扉，走自己的路，探索出属于我们自己充满意义的人生。</p><p>在开始之前，我要提一下，作家训练营（Writer’s Bootcamp）的报名将在明晚截止。</p><p>如果你想通过写作（一项不需要繁重视频剪辑和动画制作、永不过时的技能）来建立受众群体（也就是建立任何企业或将任何创意工作变现的第一步）——<a href="https://bootcamp.kortex.co/" target="_blank" rel="noreferrer">点击这里查看。</a></p><p>我愿意相信，我们提供的课程是从<em>独立思考</em>的基础教学开始的。我们给你模板和流程，但它们是为了帮助你开创自己的道路而制定的。</p><h2 id="学习如何狩猎" tabindex="-1">学习如何狩猎 <a class="header-anchor" href="#学习如何狩猎" aria-label="Permalink to &quot;学习如何狩猎&quot;">​</a></h2><p>你在生活中找不到乐趣，因为你不知道如何狩猎。</p><ul><li>你被分配了阅读材料，以通过考试。</li><li>你被分配了日常流程，以完成工作中的任务。</li><li>你被分配了信仰和价值观，以在你的文化中生存。</li></ul><p>被分配的目标的问题在于，实现它们的路径是已知的。你在做别人以前做过的事情，或者你在重复一个有远见的人分配给你的任务，去建立他们的梦想，而不是你自己的。</p><p>你的心灵，或者说大脑，天生就是为了生存而狩猎的。</p><p>如果你把一只黑猩猩每天8小时关在亮着荧光灯的办公隔间里，你觉得它会茁壮成长吗？</p><p>当然不会。它缺乏有助于其心理健康的自然环境。你不需要科学论文就能得出这个结论。</p><p>当你在工作中日复一日地执行相同的任务时，就不再有学习了。不再有挑战。不再有成长。</p><p>你唯一的选择是：</p><ol><li>关注可预测的未来并感到焦虑，因此你用干扰来麻痹自己的大脑。</li><li>关注熟悉的过去并感到无聊，因此你再次用干扰来麻痹自己的大脑。</li><li>设定一个新目标，这样你就能最终掌控自己的生活，并开始在未知中探索——这是你唯一可以学习、成长和扩展边界的地方。</li></ol><p>如果你没有目标，唯一的选择就是分心。</p><p>“狩猎”就是去发现那些能帮助你实现为自己设定的目标的知识、技能、想法和机会。</p><p>而一旦这些目标变得已知且确定，你必须准备好下一个目标，这样你才不会迷失。</p><p>这就引出了第一步。</p><h3 id="_1-指明方向的愿景" tabindex="-1">1) 指明方向的愿景 <a class="header-anchor" href="#_1-指明方向的愿景" aria-label="Permalink to &quot;1) 指明方向的愿景&quot;">​</a></h3><p>世界上最伟大的艺术家、创始人和创作者都是有远见的人。</p><p>关于他们希望未来是什么样子，他们脑海中有一幅不断演变的画面。</p><p>你的愿景就是你一生的事业。</p><p>你的愿景就是史蒂芬·科特勒（Steven Kotler）所描绘的“宏大变革目标”（Massively Transformative Purpose），这是实现不可能之事的关键一步。</p><p>你的愿景就是你一生的任务，正如罗伯特·格林（Robert Greene）所指出的那样，这是通向美好生活的关键。</p><p>正如我所说，你的愿景是一幅不断演变的画面。</p><p>通过意识到你不想要什么并反抗它，你会发现你真正想要的是什么。</p><p>你的愿景会时隐时现。</p><p>你以前曾感受过它的力量。</p><p>当你的愿景清晰时，利用那股能量。</p><p>当你的愿景模糊时，保持开放的心态，去接纳生活试图给你的教训。</p><h3 id="_2-带来清晰度的目标" tabindex="-1">2) 带来清晰度的目标 <a class="header-anchor" href="#_2-带来清晰度的目标" aria-label="Permalink to &quot;2) 带来清晰度的目标&quot;">​</a></h3><p>设定一个10年目标。</p><p>设定一个1年目标。</p><p>设定月度目标。</p><p>设定每周目标。</p><p>设定每日目标。</p><p>然后，把它们全忘了。</p><p>你需要目标来重新调整你的大脑，将其引向你必须养成的习惯，从而创造你所选择的未来。</p><p>你需要目标，以便建立能够实现这些目标的系统。</p><p>你需要目标，这样你那宛如模式识别机器的大脑，就能注意到并存储有助于实现这些目标的信息。</p><p>你可能无法实现所有这些目标。</p><p>它们可能也无法让你保持动力。</p><p>用它们来逆向推导你需要做什么才能达到你的愿景，然后把它们抛诸脑后。</p><h3 id="_3-推动进展的系统" tabindex="-1">3) 推动进展的系统 <a class="header-anchor" href="#_3-推动进展的系统" aria-label="Permalink to &quot;3) 推动进展的系统&quot;">​</a></h3><blockquote><p>赢家和输家拥有相同的目标。——詹姆斯·克莱尔（James Clear）</p></blockquote><p>没有目标，系统就无法存在；没有系统，目标也就无法实现。</p><p><em>什么是系统？</em></p><p>用与你生活相关的术语来说，它是一系列导向特定结果的行动或流程。</p><p>我们在你生活中重要领域的习惯、例行公事、仪式感、刻意练习和重复行为中都能看到这些系统的身影。</p><p>我们谈论的是与自我设定的目标相一致的有意识的系统。而不是为了完成被分配的目标而盲目遵循的已知系统。这两者有天壤之别。</p><p>自我设定的目标在实现后会进化。</p><p>被分配的目标一成不变，而实现它们的方式会随着时间的推移变得更加高效，并最终被技术取代。</p><p>如果你想赚钱，你需要一个每天写内容来产生流量的系统。</p><p>如果你想健身，你需要一个训练和饮食系统，最好是一个你觉得愉快且可持续的系统。</p><p>如果你想要更好的人际关系，你需要一个沟通与连结的系统。</p><p>没有哪个系统是放之四海而皆准的。</p><p>完全掌控你未来的途径，是用一个独特的系统解决你自己的问题，然后一遍又一遍地卖掉这个解决方案，并随着社会中个人和集体问题的演变而不断进化。这就是你适应环境的方式。</p><p>你现在就能在社交媒体上看到这种情况。有些个体卖衣服，有些卖防蓝光眼镜，还有的卖知识、卖软件等等。越来越少的企业化，越来越多的个体化。</p><p><em>你如何创建一个系统？</em></p><p>自我实验。</p><p>没有人能教你“该怎么做”。他们只能教你“他们是怎么做的”。</p><ul><li><strong>研究别人已经取得成功的流程。</strong> 你可以在社交媒体、课程里，或者简单地在谷歌上搜索找到这些。</li><li><strong>试验各种技巧。</strong> 实施你学到的流程，并尝试取得成果。</li><li><strong>发现模式和原则。</strong> 注意它们之间的相似之处，并加倍投入到这些方面。</li><li><strong>创建你自己的流程。</strong> 根据你独特的生活方式和处境，调整你所学到的东西。</li><li><strong>通过传承将其贡献给真正的教育。</strong> 给人们提供在学校里学不到的、以批判性思维为基础的教育。</li></ul><p>如果你想学习如何追求自己的兴趣，建立系统，并将它们打包成高杠杆的数字产品出售——<a href="https://mentalmonetization.com/" target="_blank" rel="noreferrer">请查看《思维变现》（Mental Monetization）。</a></p><h3 id="_4-带来觉察力的开放心态" tabindex="-1">4) 带来觉察力的开放心态 <a class="header-anchor" href="#_4-带来觉察力的开放心态" aria-label="Permalink to &quot;4) 带来觉察力的开放心态&quot;">​</a></h3><blockquote><p>传统教育和过度专业化是一种让人们屈从于主导范式/系统的方式。去研究自然界普遍的原则，成为一个具备深度素养的通才。——丹尼尔·施马克滕贝格（Daniel Schmachtenberger）</p></blockquote><p>很多人不想听这个，但学校的建立就是为了让你保持心胸狭隘和愚昧无知。</p><p>你被给定了一个等级森严的目标去追求。</p><p>你在一个细分领域里学习，只为了获得那个细分领域所提供的虚假声望。</p><p>你想要那个学位，即使你内心深处知道，没有它你也能大获成功，所以你学的唯一东西都得与那个学位挂钩。到了你拿到学位的时候，你根本没有受到真正的教育。你只是花了4年时间，学着把自己的路走窄，走向有限的机会和潜在的被取代。教育不是设定程序。</p><p>奴隶被期望终生只执行一项任务。</p><p>而自由人则被期望一生中做很多事情，因为这能带来力量、灵活性、基于原则的决策能力，以及凭借全面的技能组合来改变方向的能力，从而几乎能确保成功。</p><p>如果你刚刚开始走自己的路，这将是一个艰难的过渡。</p><p>你的大脑会封闭起来，对任何威胁你世界观的事物产生抵触反应。</p><p>社交媒体？那太毒了。全是梗图和负能量。</p><p>创业？那是给本来就有钱的人准备的，而不是给那些想开始赚更多钱的人。</p><p>写作？那只适合英语专业、学者和作家。我肯定不是每天都在发信息试图说服朋友。我也肯定没法提供某种形式的价值，并在网上找到更多志同道合的人。</p><p>当你察觉到自己的负面反应时，你必须练习敞开心扉。</p><p>你必须敢于戳穿自己的那套狗屁*话。</p><p>你必须看透老一辈人灌输进你脑子里的那些想法和信念，因为它们正在蒙蔽你的潜力，而你甚至毫无察觉。</p><p>与其产生应激反应并用分心来逃避问题，不如敞开心扉，全面思考所有视角，而不仅仅是那个阻碍你行动并让你继续当奴隶的视角。</p><h3 id="_5-解决问题的能动性" tabindex="-1">5) 解决问题的能动性 <a class="header-anchor" href="#_5-解决问题的能动性" aria-label="Permalink to &quot;5) 解决问题的能动性&quot;">​</a></h3><p>员工和创业者之间的区别在于能动性。</p><p>员工是被抛给一个问题去解决，以此来实现他们所工作公司的目标。</p><p>而创业者则是主动发现并解决问题，不需要请求任何人的许可，否则他们永远无法实现自己的目标。</p><p>在Kortex，我很感激我们团队里的每一个人都具有高度的能动性。</p><p>他们不是员工，他们是与其他创业者合作的创业者。</p><p>他们对我们的产品抱有相同的愿景。当他们发现问题时，他们会解决它，并与我们分享解决方案，即使我们需要对这个解决方案做些小调整。但哪怕是这样，如果连解决方案都不存在，我们就更不可能去改进它了。</p><p>举个例子，我们的一位开发人员 Ian 有天突发奇想，带着一个完全重新设计的应用程序跑来找我们。这让我们进度落后了一点，但如果没有他的主动性，这款应用的质量就不可能实现指数级的飞跃。</p><p>在你自己的生活中，如果你想在未来几年保持竞争力不被淘汰，就不能把安全感寄托在任何人身上。</p><p>问题将永远存在。</p><p>如果你不能发现它们，你就输了。</p><p>如果你不允许自己去解决它们，你就输了。</p><h3 id="_6-提供独特解决方案的创造力" tabindex="-1">6) 提供独特解决方案的创造力 <a class="header-anchor" href="#_6-提供独特解决方案的创造力" aria-label="Permalink to &quot;6) 提供独特解决方案的创造力&quot;">​</a></h3><blockquote><p>不幸的是，我们中的大多数人正沦为纯粹的技术人员。我们通过考试，掌握这种或那种技术，只是为了谋生；但是，如果在获取技术或发展能力时忽视了内在状态，就会给世界带来丑陋与混乱。如果我们在内在唤醒创造性的美，它就会向外表达出来，那时就会有秩序。——克里希那穆提 (Krishnamurti)</p></blockquote><p>什么是创造力？</p><p>当你剥开设计师和电影制作人等被贴上“创意”标签的技能和身份的表象时，这是一个极难回答的问题。但即使是这些“创意人士”，在工作中仍然可能会遵循令人麻木的机械化流程。</p><p>在我眼中，创造力是为意识带来秩序的过程。去拥抱混乱，收集散落的点，将它们连接起来，并用这些点进行创造：</p><ul><li>从不确定中创造确定</li><li>从无意义中创造意义</li><li>从混乱中创造清晰</li><li>从分心中创造专注</li><li>从噪音中创造信号</li><li>从无中创造有</li><li>从失败中创造成功</li><li>从挣扎中创造意义</li><li>从死亡中创造生命</li><li>从消极中创造积极</li></ul><p>正如克里希那穆提在上面所说，我们大多数人正沦为技术人员。沦为机器人。</p><p>难怪人们如此害怕失去工作并被取代。他们缺乏创造力。他们不是创作者（creators）。</p><p>机器能在30秒内解决一个过去需要人类花几百小时才能解决的问题。</p><p>这意味着，如果你在一家大公司里只是按部就班地完成一连串派发给你的任务，那么你<em>是否</em>会被取代根本不是问题，问题是<em>何时</em>被取代。</p><p>大多数忧心忡忡的人不明白的是，问题永远不会消失。</p><p>人工智能或许能<em>帮助</em>解决我们的基本需求，但我们的成长需求呢？那些伴随技术效率提升而出现的——人们无法预测的——新问题呢？</p><p>这不是什么新鲜事，只是发生的速度比以往任何时候都要快，这意味着被取代的几率比以前更高了，除非你去适应。</p><p>人工智能能解决对挑战、健康、联系、意义、灵性的需求，以及所有那些无法被简化为外部解决方案的自我实现（self-actualization）层面的需求吗？</p><p>这照亮了正在兴起的“意义经济”（Meaning Economy）。</p><p>去解决你自己的问题，并出售独特的解决方案。</p><p>去潜入未知，把心思放在对未来的愿景上，收集能让你将其变为现实的知识和技能，并将你的发现分发给他人，以统一意识。</p><p>去创造，或是被创造。</p><p>在一篇题为《ChatGPT是扯淡 (Bullh*t)》的研究论文中（这算是计算机科学家 Arvind Narayanan 和 Sayash Kapoor 之前宣称“ChatGPT是个扯淡生成器”的某种续篇）：</p><blockquote><p>因为这些程序本身不可能关心真相，也因为它们被设计成用来生成看起来像真理、但实际上毫不关心真相的文本，所以把它们的输出称为扯淡 (bullsh*t) 似乎是恰当的。”</p></blockquote><p>在我看来，机器最大的缺陷是它们缺乏意识体验。</p><p>如果你能驾驭自我反思意识这个单一却无限复杂的特质，你就有机会生存下来。</p><p>也就是说，如果你学会用你<em>头脑</em>的创造力来赚钱（或生存）——而不是依靠时间、劳动力、外表、地位、声望、施舍或任何其他变幻无常且可替代的物质资源——你就解锁了一种专属于真正富有之人的力量。</p><h2 id="赚钱是一项元技能" tabindex="-1">赚钱是一项元技能 <a class="header-anchor" href="#赚钱是一项元技能" aria-label="Permalink to &quot;赚钱是一项元技能&quot;">​</a></h2><p>对于那些与金钱关系不好的人来说，这听起来可能很肤浅。</p><p>“赚钱”是你所能学到的最有价值的技能。</p><p>我并不是指遵循诸如“学习一项有市场需求的技能，然后作为自由职业者或开家外包代理公司把它卖出去”这种陈词滥调。那只是另一个会限制你思维、让你变蠢的任务罢了。</p><p>我的意思是，你要懂得如何在任何环境下赚钱。</p><p>即使某项技能已经过时。</p><p>即使人工智能将威胁到所有工作。</p><p>即使你明天失去拥有的一切。</p><p>你的任务是达到这样一个境界：你拥有绝对的自信，相信自己可以在任何环境下取得成功。你不再依赖别人的供养。</p><p>如果你被迫要在明天之前赚到1万美元，而你不知道该怎么做，那你就有的忙了。而且，是的，对于那些曾和我有着相似心态的人来说，这是可能做到的。实际上非常有可能，只是我们太习惯于把一定数额的钱与一定数量的工作挂钩了。</p><p>创业精神是你在现代社会谋生狩猎的方式。</p><p>为什么？</p><p>因为真正的创业精神要求你能够抵御未来风险。</p><p>那么，你要如何赚钱？如何成为一名创业者？如何抵御未来风险？</p><p>它表面上很简单，但在深度上却很复杂，正如所有有意义的事物一样：</p><ol><li>通过创造力、实验和经验来创造价值（提升自我）。</li><li>通过注意力、媒体和说服力来分发价值（改善人类）。</li></ol><p>当<em>你</em>掌控着愿景时，人工智能和技术就会成为工具，而不是主人。</p><p>那个简单流程的绝妙之处在于，它永无止境。</p><p>价值随时间而进化。</p><p>价值就是认知。</p><p>意思是，你必须把正确的东西交给正确的人，他们才会认为它有价值（他们才会付钱给你）。</p><p>婴儿潮一代会认为黄金比比特币更有价值，除非你在他们常待的地方，用有说服力的媒体出现在他们面前，说服他们改变看法。</p><p>我们已经在上一节中学习了如何创造价值：</p><p>解决你自己的问题，并出售解决方案。</p><p>最好是在那些永恒的市场里：健康、财富、人际关系和幸福。</p><h3 id="现代分发——如何将你的价值展现在正确的人面前" tabindex="-1">现代分发——如何将你的价值展现在正确的人面前 <a class="header-anchor" href="#现代分发——如何将你的价值展现在正确的人面前" aria-label="Permalink to &quot;现代分发——如何将你的价值展现在正确的人面前&quot;">​</a></h3><p>价值的分发自古以来就一直存在，但它采取了许多不同的形式。</p><p>在当下这个时代，最容易触达的分发形式就是在互联网上写作：</p><p>社交媒体、电子邮件（这也是我此刻抓住你注意力的地方）、变成 YouTube 视频和播客音频的脚本等等。</p><p>写作能让你成为一家一人媒体公司。</p><p>你可以在 X 上写一篇文章，然后将其交叉发布在 Instagram 和 LinkedIn 上。</p><p>你可以把那篇文章变成脚本，然后作为 Reel、Short 或 TikTok 视频发布。</p><p>你可以挑选出你最好的帖子，将它们扩展成推特长文或时事通讯，然后将其重新利用，制作成轮播图、视频脚本和播客节目。</p><p>更好的是，作为一名写作者，如果你不想的话，你甚至不用露脸，也不用剪辑视频。</p><p>你只需在早晨坐下来，与纸上的文字融为一体。这是一种非常有意义的生活方式，也是提升自我的途径。</p><p>通过教导他人、整理思绪以及获取对你想法的反馈，你能学到更多。它是成长与价值的催化剂。</p><p>就像你所看出的那样，我崇尚将成功建立在应用于现代环境（这个环境还会不断变化）的永恒原则之上。写作、演讲、说服力、创业精神、创造力……这些都是自最初两个人相互接触以来就存在的东西。</p><p>用于分发它们的媒介，比如平面设计软件、网页设计、电子邮件平台，以及人们告诉你要去学的其他“有市场需求的技能”，确实可能很有价值，但前提是它们不能成为一种缺乏底层基础（正是这种基础使它们发挥作用）的单一技能。</p><p>你可以找一份网页设计师的工作，或者用 AI 做一个网站，但你无法掌控愿景。你无法掌控人们是否认为这对他们自己的生活有价值。</p><p>如果你还没有“开窍”，你可以通过以下方式随时随地赚钱：</p><ul><li>基于你为自己解决的一个问题，创造一款产品或服务。</li><li>在当今注意力<em>汇聚的地方</em>——互联网——建立受众群体。</li><li>以一种有说服力的方式提供你的产品或服务，从而实现受众变现。</li></ul><p>商业和创业精神一直以来都是一样的。</p><p><em>建立受众，受众变现。</em></p><p>“企业”只是一个法律框架，它允许你构建针对某个问题的解决方案并因此获得报酬。</p><p>你的祖先不需要这个法律框架也能谋生，他们可以直接交换商品和服务。</p><p><strong>我们来回顾一下。</strong></p><p>通过创建一个系统来实现一个自发生成的目标。</p><p>专注于健康、财富、人际关系和幸福。</p><p>将那个系统变成一款能够帮助拥有相同问题的人的产品或服务。</p><p>我建议从 <a href="https://mentalmonetization.com/" target="_blank" rel="noreferrer">Mental Monetization</a> 开始，这样你就能在构建软件或其他重资产初创公司之前，建立起现金流。</p><p>通过写给自己看来建立受众，这样你就能吸引那些与你有相同愿景、因而面临相同问题的人，让他们看到你系统的价值并买单。</p><p>写下你的观点、信念和思维方式。教授你的兴趣和技能。分享你最喜欢的想法。向人们展示你是如何解决问题的。分享你的愿景，让其他人产生共鸣。</p><p>如果你想优先学习写作而不是演讲或视频等其他技能——<a href="https://bootcamp.kortex.co/" target="_blank" rel="noreferrer">作家训练营的报名将在明晚截止。</a></p><p>然后，迭代，迭代，再迭代。</p><p>不要被客户工作困住。不要被单一产品困住。在生活和事业中不断解决涌现的问题。永远不要停止成长和进化。</p><p>你会知道下一步该做什么。</p><p>—— Dan</p><hr><p><a href="/en/letters/learn-this-skill-if-you-want-to-stay-relevant-in-10-years">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',195))])}const q=t(h,[["render",c]]);export{_ as __pageData,q as default};
